<script lang="ts">
 import {invalidateAll} from '$app/navigation';
 import MailDialog from '$lib/components/newsletter/MailDialog.svelte';
 import MailNav from '$lib/components/newsletter/MailNav.svelte';
 import {readContactCsv,contactRows,readContactArchive,type ContactArchive} from '$lib/newsletter-csv';
 let {data}=$props();
 const labels:Record<string,string>={active:'配信可能',unconfirmed:'同意未確認',unsubscribed:'配信停止',bounced:'バウンス',complained:'苦情による抑止'};
 let message=$state(''),busy=$state(false),csv=$state<{headers:string[];rows:string[][]}|null>(null),emailColumn=$state(''),nameColumn=$state(''),importStatus=$state('unconfirmed'),tag=$state(''),consent=$state(''),fileName=$state(''),preview=$state(false),listName=$state(''),listTags=$state('');
 let edit=$state<{id:string;version:number;name:string;tags:string;email:string;status:string;fields:Record<string,unknown>}|null>(null),suppress=$state(false);
 let archive=$state<ContactArchive|null>(null);
 let customFields=$state(''),profileMessage=$state(''),activity=$state<Record<string,any>[]>([]),stats=$state<Record<string,number>|null>(null);
 async function openContact(c:typeof data.contacts[number]){edit={...c,tags:c.tags.join(', '),fields:c.fields as Record<string,unknown>};suppress=false;activity=[];stats=null;profileMessage='反応履歴を読み込み中…';customFields=JSON.stringify(Object.fromEntries(Object.entries(edit.fields).filter(([k])=>!['benchmark_lists','benchmark_status_sources'].includes(k))),null,2);const contactId=c.id;try{const r=await api('profile',{id:contactId});if(edit?.id===contactId){activity=r.activity;stats=r.stats;profileMessage='';}}catch(e){if(edit?.id===contactId)profileMessage=String(e);}}
 async function api(action:string,value:unknown){const f=new FormData();f.set('facility',data.facility);f.set('action',action);f.set('data',JSON.stringify(value));const r=await fetch('/admin/mail/api',{method:'POST',body:f}),j=await r.json();if(!r.ok)throw Error(j.error);return j.data;}
 async function loadFile(e:Event){message='';preview=false;csv=null;archive=null;try{const file=(e.currentTarget as HTMLInputElement).files?.[0];if(!file)return;if(file.size>10*1024*1024)throw Error('10MiB以内のファイルを選択してください。');fileName=file.name;if(file.name.toLowerCase().endsWith('.json')){archive=readContactArchive(await file.text());return;}csv=await readContactCsv(file);emailColumn=csv.headers.find(h=>/^(email|メールアドレス)$/i.test(h))??'';nameColumn=csv.headers.find(h=>/^(name|氏名|名)$/i.test(h))??'';}catch(e){message=String(e);}}
 function check(){try{if(!csv)return;contactRows(csv,emailColumn,nameColumn,importStatus,tag,consent);preview=true;message='全行の形式を確認しました。';}catch(e){preview=false;message=String(e);}}
 async function importFile(){if((!csv&&!archive)||!preview||busy)return;busy=true;let done=0;try{const rows=archive?.contacts??contactRows(csv!,emailColumn,nameColumn,importStatus,tag,consent);for(let i=0;i<rows.length;i+=200){await api('import',{name:fileName,rows:rows.slice(i,i+200)});done=Math.min(i+200,rows.length);message=`${done.toLocaleString()} / ${rows.length.toLocaleString()} 件を取り込みました。`;}
 if(archive){for(const list of archive.lists)await api('list',list);}else if(tag.trim())await api('list',{name:tag.trim(),tags:[tag.trim()]});csv=null;archive=null;preview=false;await invalidateAll();message=`${done.toLocaleString()}件の取り込みが完了しました。既存の配信停止・抑止を維持しました。`;
 }catch(e){message=`${done}件まで取り込み済みです。${String(e)} 同じファイルを再実行してもメールアドレス単位で統合されます。`;}finally{busy=false;}}
 async function saveContact(){if(!edit||busy)return;busy=true;try{let fields:unknown;try{fields=JSON.parse(customFields);}catch{throw Error('カスタム項目は正しいJSONで入力してください。');}if(!fields||typeof fields!=='object'||Array.isArray(fields))throw Error('カスタム項目は項目名と値のオブジェクトで入力してください。');await api('profile',{id:edit.id,update:{version:edit.version,name:edit.name,tags:edit.tags.split(',').map(t=>t.trim()).filter(Boolean),suppress,fields}});edit=null;await invalidateAll();message='更新しました。';}catch(e){message=String(e);}finally{busy=false;}}
 const pageUrl=(n:number)=>'?'+new URLSearchParams({q:data.q,status:data.status,field:data.field,page:String(n)});
</script>
<svelte:head><title>コンタクト ｜ メルマガ</title></svelte:head>
<MailNav active={data.tab==='lists'?'lists':'contacts'}/>
<header class="mb-6"><h1 class="text-2xl font-semibold">{data.tab==='lists'?'リスト・タグ':'コンタクト'}</h1><p class="mt-2 text-sm text-stone-500">同じメールアドレスは1人として管理し、複数のリストにはタグで所属します。</p></header>
{#if message}<p role="status" class="mb-4 rounded-lg border border-amber-200 bg-amber-50 p-4">{message}</p>{/if}
{#if data.tab==='lists'}
 <section class="panel mb-6"><h2>リストを作成</h2><label>リスト名<input bind:value={listName}/></label><label>対象タグ（カンマ区切り・いずれかに一致）<input bind:value={listTags}/></label><button disabled={!listName.trim()||!listTags.trim()} onclick={async()=>{try{await api('list',{name:listName.trim(),tags:listTags.split(',').map(t=>t.trim()).filter(Boolean)});listName='';listTags='';await invalidateAll();}catch(e){message=String(e);}}}>保存</button></section>
 <div class="grid gap-4 md:grid-cols-3">{#each data.lists as list}<article class="panel"><h2>{list.name}</h2><p class="text-sm text-stone-500">{list.tags.join(' / ')}</p></article>{:else}<p>リストはまだありません。</p>{/each}</div>
{:else}
 <form method="GET" class="mb-4 flex flex-wrap items-end gap-3"><label>検索対象<select name="field" value={data.field}><option value="email">メールアドレス</option><option value="name">名前</option></select></label><label>検索<input name="q" value={data.q}/></label><label>状態<select name="status" value={data.status}><option value="">すべて</option>{#each Object.entries(labels) as [v,l]}<option value={v}>{l}</option>{/each}</select></label><button>絞り込む</button><span class="py-3 text-sm">{data.count.toLocaleString()}件</span></form>
 <div class="overflow-auto rounded-xl border border-stone-200 bg-white"><table class="w-full text-left text-sm"><thead class="bg-stone-50"><tr><th>メールアドレス</th><th>名前</th><th>状態</th><th>タグ</th></tr></thead><tbody>{#each data.contacts as c}<tr class="border-t border-stone-100"><td><button class="border-0 text-left underline" onclick={()=>void openContact(c)}>{c.email}</button></td><td>{c.name}</td><td>{labels[c.status]}</td><td>{c.tags.join(' / ')}</td></tr>{:else}<tr><td colspan="4">該当するコンタクトはありません。</td></tr>{/each}</tbody></table></div>
 <nav aria-label="ページ" class="my-4 flex items-center gap-5">{#if data.page>1}<a href={pageUrl(data.page-1)}>← 前へ</a>{/if}<span>{data.page}ページ</span>{#if data.page*50<data.count}<a href={pageUrl(data.page+1)}>次へ →</a>{/if}</nav>
 <details class="panel mt-8"><summary class="cursor-pointer font-semibold">CSVからコンタクトを取り込む</summary><p class="my-4 text-sm text-stone-500">UTF-8／Shift-JIS対応。状態別のCSVを指定してください。既存の配信停止・バウンス・苦情は、配信可能なCSVを取り込んでも解除しません。</p>
 <input type="file" accept=".csv,.json,text/csv,application/json" onchange={loadFile} disabled={busy}/>
 {#if archive}<div class="my-5 space-y-3"><h2>移行ファイルの確認</h2><p>{archive.contacts.length.toLocaleString()}コンタクト・{archive.lists.length}リスト</p><div class="flex flex-wrap gap-4 text-sm">{#each Object.entries(labels) as [s,label]}<span>{label}：{archive.contacts.filter(c=>c.status===s).length.toLocaleString()}件</span>{/each}</div><label class="flex gap-2"><input type="checkbox" bind:checked={preview} disabled={busy}/>上記の配信状態・所属リストを引き継ぐことを確認しました</label><button class="primary" disabled={!preview||busy} onclick={()=>void importFile()}>{busy?'取り込み中…':'移行データを取り込む'}</button></div>{/if}
 {#if csv}<div class="mt-4 grid gap-4 md:grid-cols-2"><label>メールアドレス列<select bind:value={emailColumn} onchange={()=>preview=false}><option value="">選択</option>{#each csv.headers as h}<option>{h}</option>{/each}</select></label><label>名前列<select bind:value={nameColumn} onchange={()=>preview=false}><option value="">指定なし</option>{#each csv.headers as h}<option>{h}</option>{/each}</select></label><label>このCSVの状態<select bind:value={importStatus} onchange={()=>preview=false}>{#each Object.entries(labels) as [v,l]}<option value={v}>{l}</option>{/each}</select></label><label>所属タグ<input bind:value={tag} oninput={()=>preview=false}/></label><label class="md:col-span-2">配信同意の根拠（配信可能を選ぶ場合は必須）<input bind:value={consent} oninput={()=>preview=false} placeholder="例：Benchmarkの既存メール会員・配信可能リストから移行"/></label></div>
 <p class="my-4">{csv.rows.length.toLocaleString()}件。取り込み状態：{labels[importStatus]}</p><div class="flex gap-3"><button onclick={check} disabled={busy}>内容を確認</button><button class="primary" onclick={()=>void importFile()} disabled={!preview||busy}>{busy?'取り込み中…':'この内容で取り込む'}</button></div>{/if}
 <h2 class="mt-6">取り込み履歴</h2>{#each data.imports as imp}<p class="mt-2 text-sm">{new Date(imp.created_at).toLocaleString('ja-JP')} ／ {imp.name} ／ {imp.imported}件・抑止{imp.suppressed}件</p>{/each}
 </details>
{/if}
{#if edit}<MailDialog title="コンタクト編集" onDismiss={()=>edit=null}><section class="panel space-y-4">
 <h2>{edit.email}</h2><p>{labels[edit.status]}</p><label>名前<input bind:value={edit.name}/></label><label>タグ（カンマ区切り）<input bind:value={edit.tags}/></label>
 <details><summary>カスタム項目</summary><label>項目名と値（JSON）<textarea class="w-full border p-3 text-sm" rows="8" bind:value={customFields}></textarea></label><p class="text-sm text-stone-500">移行元リスト・状態の証跡は自動で保持されます。</p></details>
 {#if ['active','unconfirmed'].includes(edit.status)}<label class="flex gap-2"><input type="checkbox" bind:checked={suppress}/>配信を停止する</label>{/if}
 <div class="flex gap-3"><button onclick={()=>edit=null}>閉じる</button><button class="primary" disabled={busy} onclick={()=>void saveContact()}>保存</button></div>
 <hr/><h2>配信への反応</h2>{#if profileMessage}<p role="status" class="text-sm">{profileMessage}</p>{/if}
 {#if stats}<div class="grid grid-cols-3 gap-3 text-sm"><p>送信 {stats.sent}件</p><p>開封 {stats.opened}件</p><p>クリック {stats.clicked}件</p></div>{/if}
 <p class="text-sm text-stone-500">Bookで配信した最新100件。テストは含みません。追跡情報は受信環境によって実際の閲覧と異なる場合があります。</p>
 {#each activity as a}<article class="border-t pt-3 text-sm"><a class="underline" href={'/admin/mail/'+a.campaign_id}>{a.name}</a><p>{new Date(a.created_at).toLocaleString('ja-JP')} ／ {a.state}</p>{#if a.opened_at}<p>開封：{new Date(a.opened_at).toLocaleString('ja-JP')}</p>{/if}{#if a.clicked_at}<p>クリック：{new Date(a.clicked_at).toLocaleString('ja-JP')}</p>{/if}{#if a.error}<p class="text-red-700">{a.error}</p>{/if}</article>{:else}{#if !profileMessage}<p class="text-sm">Bookからの配信履歴はありません。</p>{/if}{/each}
 </section></MailDialog>{/if}
<style>
 .panel{padding:24px;border:1px solid #e7e5e4;border-radius:12px;background:white}.panel h2{font-size:18px;font-weight:600}.panel>label{margin:16px 0}label{display:block;font-size:14px}input:not([type=checkbox]),select{display:block;margin-top:6px;padding:10px;border:1px solid #d6d3d1;border-radius:7px;width:100%;font-size:14px}button{min-height:44px;border:1px solid #d6d3d1;border-radius:8px;padding:10px 16px;background:white;font-size:14px}button:hover{background:#f5f5f4}button:disabled{opacity:.45}.primary{background:#292524;color:white}.primary:hover{background:#44403c}th,td{padding:14px 16px}
</style>
